package admin

const pageTemplate = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MCP Gateway · Servers</title><style>` + adminCSS + `</style>{{if not .Login}}<script src="/admin/actions.js" defer></script>{{end}}</head><body><main>{{if .Login}}<section><h1>MCP Gateway</h1><p>Sign in with your separate administrator token.</p><form method="post" action="/admin/login"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Administrator token<input type="password" name="token" required autocomplete="current-password" maxlength="4096"></label><button>Sign in</button></form></section>{{else}}<header class="page-header"><div><h1>MCP servers</h1><p>Connect servers and enable the tools you want to use.</p><p class="muted identity">{{if .Authentik}}Signed in as {{.User}} via {{.AuthProvider}}. Sign out ends this application session.{{else}}Signed in with administrator token.{{end}}</p></div><form method="post" action="/admin/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="secondary">Sign out</button></form></header><nav class="admin-nav" aria-label="Administration"><a href="/admin/servers" aria-current="page">Servers</a><a href="/admin/connection">Connection</a></nav>
{{if .Error}}<section role="alert"><p>{{.Error}}</p></section>{{end}}<section><details {{if .Draft}}open{{end}}><summary>Add a server</summary><form method="post" action="/admin/servers/create"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Revision}}"><div class="grid"><label>Stable server ID<input name="id" value="{{index .Draft "id"}}" required maxlength="128" pattern="[a-zA-Z0-9][a-zA-Z0-9_.:\-]*"></label><label>Description<input name="description" value="{{index .Draft "description"}}" maxlength="2000"></label></div><label>Keywords, separated by commas<input name="keywords" value="{{index .Draft "keywords"}}" maxlength="2000"></label><label>Saved MCP endpoint<input name="url" value="{{index .Draft "url"}}" type="url" required maxlength="2048" placeholder="https://example.com/mcp"></label><label><input type="checkbox" name="https_consent" value="yes" {{if eq (index .Draft "https_consent") "yes"}}checked{{end}}>Approve this exact HTTPS endpoint for upstream connections</label><fieldset><legend>Upstream authentication</legend><label>Authentication type<select name="auth_mode"><option value="none">None</option><option value="bearer" {{if eq (index .Draft "auth_mode") "bearer"}}selected{{end}}>Bearer token</option><option value="header" {{if eq (index .Draft "auth_mode") "header"}}selected{{end}}>Custom header</option></select></label><label>Custom header name<input name="auth_header" value="{{index .Draft "auth_header"}}" maxlength="128" placeholder="x-api-key"></label><label>Secret value<input name="secret" type="password" autocomplete="new-password" maxlength="4096"></label><p>For Custom header, enter its name and literal value. Bearer adds the Bearer prefix automatically. None requires an empty secret.</p></fieldset><p>New servers and tools start disabled. Enable a tool to allow all authenticated gateway clients to use it.</p><button>Create disabled server</button></form></details></section>
{{$root:=.}}{{range .Servers}}{{$server:=.}}<article class="server-card" data-server="{{.ID}}"><header class="server-header"><h2>{{.ID}}</h2><form data-quick method="post" action="/admin/servers/{{.ID}}/{{if .Server.Enabled}}disable{{else}}enable{{end}}"><input type="hidden" name="csrf" value="{{$root.CSRF}}"><input type="hidden" name="revision" value="{{$root.Revision}}"><button type="submit" class="switch" role="switch" aria-checked="{{.Server.Enabled}}" aria-label="Enable server {{.ID}}"><span data-switch-label>{{if .Server.Enabled}}Enabled{{else}}Disabled{{end}}</span><span class="switch-track" aria-hidden="true"></span></button></form></header><p class="server-description">{{.Server.Description}}</p><p class="endpoint">{{.Server.URL}}</p><div class="server-meta"><span class="badge" data-connection-badge data-checked="{{if .Checked}}true{{else}}false{{end}}">{{if .Checked}}Connection checked{{else}}{{if .Failed}}Check failed{{else}}Not checked{{end}}{{end}}</span><span data-tool-count>{{.EnabledTools}}/{{len .Tools}} tools enabled</span></div><p class="unavailable" data-server-unavailable {{if .Server.Enabled}}hidden{{end}}>Server disabled — tools unavailable. Tool settings are preserved.</p>


<div class="row batch-settings"><form data-batch-switch data-quick method="post" action="/admin/servers/{{.ID}}/{{if and .BatchRegistry .Server.BatchReadEnabled}}batch-disable{{else}}batch-enable{{end}}"><input type="hidden" name="csrf" value="{{$root.CSRF}}"><input type="hidden" name="revision" value="{{$root.Revision}}"><span>Batch for reads</span><button class="switch" role="switch" aria-checked="{{and .BatchRegistry .Server.BatchReadEnabled}}" aria-label="Enable batch reads on {{.ID}}" {{if not .BatchRegistry}}disabled data-fixed-disabled{{end}}><span data-switch-label>{{if and .BatchRegistry .Server.BatchReadEnabled}}Enabled{{else}}Disabled{{end}}</span><span class="switch-track" aria-hidden="true"></span></button></form><p data-batch-count>{{.BatchCount}} verified enabled reads</p>{{if not .BatchRegistry}}<p>Batch uses an operator-managed file. Connector switches require registry policy mode.</p>{{end}}</div>
<details class="tools" data-tools><summary>Tools <span class="tools-count" data-tools-count>{{.EnabledTools}}/{{len .Tools}} enabled</span></summary><div data-tool-list>{{range .Tools}}<div class="tool-row" data-tool="{{.Name}}"><details class="tool-details"><summary data-tool-name>{{.Name}}</summary><p data-description>{{.Description}}</p><p data-batch-reason>{{.BatchReason}}</p><details data-schema {{if not .Schema}}hidden{{end}}><summary>Input schema</summary><pre>{{.Schema}}</pre></details></details><form data-quick method="post" action="/admin/servers/{{$server.ID}}/{{if .Enabled}}tool-disable{{else}}tool-enable{{end}}"><input type="hidden" name="csrf" value="{{$root.CSRF}}"><input type="hidden" name="revision" value="{{$root.Revision}}"><input type="hidden" name="tool" value="{{.Name}}"><button type="submit" class="switch" role="switch" aria-checked="{{.Enabled}}" aria-label="Enable tool {{.Name}} on server {{$server.ID}}"><span data-switch-label>{{if .Enabled}}Enabled{{else}}Disabled{{end}}</span><span class="switch-track" aria-hidden="true"></span></button></form></div>{{end}}</div><p data-empty-tools {{if .Tools}}hidden{{end}}>No tools loaded yet. Enable the server or check its connection. New tools remain disabled.</p></details>
<div class="server-footer"><form data-quick method="post" action="/admin/servers/{{.ID}}/check"><input type="hidden" name="csrf" value="{{$root.CSRF}}"><input type="hidden" name="revision" value="{{$root.Revision}}"><button class="secondary">Check connection</button></form><details class="settings"><summary>Server settings</summary>{{if .BatchRegistry}}<form data-batch-profile method="post" action="/admin/servers/{{.ID}}/batch-profile"><input type="hidden" name="csrf" value="{{$root.CSRF}}"><input type="hidden" name="revision" value="{{$root.Revision}}"><label>Reviewed read profile<select name="batch_read_profile"><option value="">None</option><option value="calendar-mcp-v1" {{if eq .Server.BatchReadProfile "calendar-mcp-v1"}}selected{{end}}>Calendar MCP v1</option><option value="home-assistant-v1" {{if eq .Server.BatchReadProfile "home-assistant-v1"}}selected{{end}}>Home Assistant v1</option></select></label><p>Saving a profile turns batch off. Check and enable batch separately.</p><button>Save read profile</button></form>{{end}}<form method="post" action="/admin/servers/{{.ID}}/update"><input type="hidden" name="csrf" value="{{$root.CSRF}}"><input type="hidden" name="revision" value="{{$root.Revision}}"><label>Description<input name="description" value="{{.Server.Description}}" maxlength="2000"></label><label>Keywords<input name="keywords" value="{{range $i,$v:=.Server.Keywords}}{{if $i}}, {{end}}{{$v}}{{end}}" maxlength="2000"></label><label>Endpoint<input type="url" name="url" value="{{.Server.URL}}" required maxlength="2048"></label><label><input type="checkbox" name="https_consent" value="yes">Approve a new exact HTTPS endpoint</label>{{if .Server.TokenEnv}}<p>Existing credential source: environment variable {{.Server.TokenEnv}}.</p>{{end}}<fieldset><legend>Upstream authentication</legend><label>Authentication type<select name="auth_mode"><option value="none" {{if not .Secret}}selected{{end}}>None</option><option value="bearer" {{if and .Secret (not .Server.AuthHeader)}}selected{{end}}>Bearer token</option><option value="header" {{if .Server.AuthHeader}}selected{{end}}>Custom header</option></select></label><label>Custom header name<input name="auth_header" value="{{.Server.AuthHeader}}" maxlength="128" placeholder="x-api-key"></label><label>Replace secret value (blank keeps existing)<input type="password" name="secret" autocomplete="new-password" maxlength="4096"></label><p>Select None with an empty secret to remove saved authentication. Custom header sends the literal value without a Bearer prefix.</p></fieldset><p>Endpoint changes disable the server and clear its saved tools. Authentication type, header name or secret changes disable it and require another check.</p><button>Save settings</button></form><details class="connection-details"><summary>Connection details</summary><p>Authorization: {{if .Secret}}{{if .Server.AuthHeader}}custom header {{.Server.AuthHeader}}{{else}}Bearer token{{end}} configured{{else}}none{{end}}.</p><p data-probe-status>{{if .Checked}}Connection checked at {{.Checked}} (checked recently).{{else}}{{if .Failed}}Connection check failed at {{.Failed}}. {{end}}Enable automatically checks the connection when needed.{{end}}</p><p>Checks only list tools; they never invoke them. Enabled tools are available to authenticated gateway clients when the server is enabled.</p></details><details class="delete-details"><summary>Delete server</summary><form method="post" action="/admin/servers/{{.ID}}/delete"><input type="hidden" name="csrf" value="{{$root.CSRF}}"><input type="hidden" name="revision" value="{{$root.Revision}}"><label>Type {{.ID}} to confirm deletion<input name="confirm" required autocomplete="off"></label><p>Deletes this server and its saved credential.</p><button class="danger">Delete server</button></form></details></details></div>

<p data-action-status role="status" aria-live="polite"></p><button type="button" class="secondary" data-refresh hidden>Refresh state</button></article>{{else}}<section><p>No servers connected. Add a server above.</p></section>{{end}}{{end}}{{if not .Login}}<details class="diagnostics"><summary>Page details</summary><p class="muted">Registry revision <span data-revision>{{.Revision}}</span>. Changes apply to subsequent requests. Connection checks list tools and never invoke them.</p></details>{{end}}</main></body></html>`

const adminCSS = `.batch-settings{margin:12px 0;padding:12px;background:#f5f7fa;border-radius:6px}.batch-settings form{display:flex;align-items:center;justify-content:space-between;gap:12px}[data-batch-reason]{font-size:13px;color:#536178}
.key-buttons{display:flex;flex-wrap:wrap;gap:8px}
*{box-sizing:border-box}body{margin:0;background:#f4f6f8;color:#202b3d;font:16px/1.5 system-ui,sans-serif}main{max-width:960px;margin:auto;padding:28px 24px}h1,h2,h3,p{margin:0}h1{font-size:28px;letter-spacing:-.7px}h2{font-size:19px;line-height:1.3;overflow-wrap:anywhere}h3{font-size:16px}p{margin:10px 0;color:#536178}.page-header,.server-header,.actions{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.page-header{margin-bottom:18px}.page-header p{margin:4px 0;font-size:14px}.page-header .identity{font-size:13px}.server-header{flex-wrap:nowrap;align-items:flex-start}.server-header h2{min-width:0;padding-top:10px}.server-card,section{background:white;border:1px solid #d8dfea;border-radius:12px;padding:18px;margin:12px 0;min-width:0}.server-description{font-size:14px;margin:3px 0 8px}.endpoint{font:13px/1.5 ui-monospace,monospace;color:#536178;overflow-wrap:anywhere;margin:6px 0}.server-meta{display:flex;align-items:center;flex-wrap:wrap;gap:8px;font-size:13px;margin:8px 0 8px}.badge{background:#edf0f4;color:#465568;border-radius:5px;padding:3px 7px}.badge[data-checked=true]{color:#216044;background:#edf7f1}.unavailable{font-size:13px;color:#765327;background:#fff8eb;padding:8px 10px;border-radius:6px;margin:8px 0}.server-footer{display:flex;align-items:center;gap:8px 16px;flex-wrap:wrap;margin-top:8px}.server-footer>details{flex:0 1 auto;min-width:0}.server-footer>details[open]{flex:1 0 100%}.connection-details{font-size:13px}.connection-details p{margin:8px 0}.tools{border-top:1px solid #e4e8ef;margin-top:8px}.tools>summary{padding:10px 0}.tools-count{font-weight:400;color:#536178;font-size:13px;margin-left:8px}.tool-row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:start;gap:8px;border-top:1px solid #edf0f4;padding:5px 0}.tool-details{min-width:0}.tool-details>summary{padding:12px 0;font-size:14px;overflow-wrap:anywhere}.tool-details p{font-size:14px;margin:4px 0 12px}.tool-row form{padding-top:0}.tool-row pre{font-size:12px}.switch{display:flex;align-items:center;justify-content:flex-end;gap:8px;min-width:112px;min-height:44px;border:0;background:transparent;color:#536178;font-size:13px;padding:8px 0 8px 8px}.switch[aria-checked=true]{color:#216044}.switch-track{display:inline-block;position:relative;flex:none;width:36px;height:22px;background:#7c8798;border-radius:20px}.switch-track:after{content:'';position:absolute;left:3px;top:3px;width:16px;height:16px;background:white;border-radius:50%;transition:transform .15s}.switch[aria-checked=true] .switch-track{background:#28775a}.switch[aria-checked=true] .switch-track:after{transform:translateX(14px)}label{display:block;margin:12px 0;font-size:14px}input:not([type=checkbox]),textarea,select{display:block;width:100%;min-width:0;min-height:44px;padding:10px;border:1px solid #8795ab;border-radius:6px;font:16px/1.5 system-ui,sans-serif}textarea{min-height:80px}input[type=checkbox]{width:18px;height:18px;margin-right:6px}button{min-height:44px;border:1px solid #304a76;background:#304a76;color:white;border-radius:7px;padding:9px 14px;font:inherit;cursor:pointer}button.secondary{color:#304a76;background:white}button.danger{background:#8b2939;border-color:#8b2939}.server-footer button{font-size:14px}.server-footer button.secondary{border-color:#d8dfea}.grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}details{margin:0}summary{cursor:pointer;font-weight:600;min-height:44px;padding:10px 0;overflow-wrap:anywhere}fieldset{min-width:0;border:1px solid #d8dfea;border-radius:8px;margin:16px 0;padding:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f1f4f8;padding:12px;border-radius:6px;font-size:13px}a{color:#304a76}.muted{color:#536178}.diagnostics{font-size:13px;margin-top:18px}.diagnostics summary{font-weight:400}.delete-details{margin-top:4px;font-size:13px}.delete-details>summary{color:#8b2939;font-weight:400}.settings>summary{font-size:14px}.settings p{font-size:13px}[hidden]{display:none!important}[data-action-status]:empty{display:none}[data-action-status]{font-size:14px;margin:10px 0 0}button[aria-busy=true]{cursor:progress}button:disabled{opacity:.55;cursor:not-allowed}:focus-visible{outline:3px solid #4585dc;outline-offset:3px}@media(max-width:640px){main{padding:16px 12px}h1{font-size:24px}.server-card,section{padding:12px}.grid{grid-template-columns:minmax(0,1fr);gap:0}.page-header{align-items:flex-start}.page-header>div{flex:1;min-width:0}.page-header p{font-size:13px}.server-header h2{font-size:18px}.server-meta{gap:6px}.switch{min-width:102px}.tool-details>summary{font-size:13px}.server-footer{gap:4px 12px}}@media(max-width:350px){.tool-row{column-gap:4px}.switch{min-width:94px;gap:6px;padding-left:4px}}@media(prefers-reduced-motion:reduce){.switch-track:after{transition:none}}
.admin-nav{display:flex;gap:8px;margin:12px 0 18px;flex-wrap:wrap}.admin-nav a{display:inline-flex;align-items:center;min-height:44px;padding:9px 14px;border-radius:7px;text-decoration:none}.admin-nav a[aria-current=page]{background:#e3ebf7;font-weight:600}.copy-row{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:12px 0}.copy-row input,.copy-row pre{flex:1 1 220px;min-width:0;margin:0}.key-card{margin:12px 0;padding:12px;border:1px solid #d8dfea;border-radius:8px}.key-card h3{overflow-wrap:anywhere}.one-time{border:2px solid #28775a}.one-time input{font-family:ui-monospace,monospace}.connection-page code{overflow-wrap:anywhere}.connection-page [data-key-status]{overflow-wrap:anywhere}`
